package com.hmdp.ai.runtime.node;
import com.fasterxml.jackson.databind.ObjectMapper;import com.hmdp.ai.domain.workflow.WorkflowNodeType;import org.springframework.stereotype.Component;import java.util.*;
@Component public class HumanNodeExecutor implements NodeExecutor {private final ObjectMapper mapper;public HumanNodeExecutor(ObjectMapper m){mapper=m;}public Set<WorkflowNodeType>supportedTypes(){return EnumSet.of(WorkflowNodeType.HUMAN_FEEDBACK,WorkflowNodeType.HUMAN_APPROVAL);}public NodeExecutionResult execute(NodeExecutionContext c){Map<String,Object>u=new LinkedHashMap<>();u.put("waitingNode",c.getNode().getCode());u.put("waitingType",c.getNode().getType().name());return new NodeExecutionResult(com.hmdp.ai.domain.run.NodeRunStatus.WAITING,mapper.valueToTree(u),null,u,null,null,null,com.hmdp.ai.domain.run.UsageSummary.empty(0),false,null);}}
